function pipelineNodes(){const supplied=list(state.pipeline?.nodes);if(supplied.length)return supplied;const configured=list(active('logic')?.data.nodes).map(n=>({...n,label:nodeTitles[n.id]||labels[n.prompt_key]?.replace('提示词','')||n.id,state:'pending',depends_on:list(n.depends_on).length?n.depends_on:['data']}));return [{id:'data',label:'MT5 指标',state:'pending',depends_on:[]},...configured,{id:'gateway',label:'执行',state:'pending',depends_on:configured.length?[configured.at(-1).id]:['data']}];}
async function api(path,body,method='POST'){
  const opts={method,headers:{Accept:'application/json'},cache:'no-store'};
  if(method!=='GET'){if(!state.token)throw new Error('本地服务尚未连接');opts.headers['X-Fusion-Token']=state.token;if(body!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body);}}
  const controller=new AbortController();opts.signal=controller.signal;const timer=setTimeout(()=>controller.abort(),['/api/cycle','/api/backtest','/api/ai/test','/api/background/refresh'].includes(path)?240000:20000);
  try{const response=await fetch(path,opts);let data;try{data=await response.json();}catch{throw new Error(`响应内容异常（HTTP ${response.status}）`);}if(!response.ok){const detail=typeof data.detail==='string'?data.detail:Array.isArray(data.detail)?data.detail.map(e=>`${e.loc?.join('.')||''}: ${e.msg}`).join('；'):`请求失败（HTTP ${response.status}）`;throw new Error(detail);}return data;}
  catch(e){if(e.name==='AbortError')throw new Error('请求超时，请先刷新确认后端结果');if(e instanceof TypeError)throw new Error('无法连接本地服务');throw e;}finally{clearTimeout(timer);}
}
function toast(message,error=false){clearTimeout(state.toastTimer);$('toast').textContent=message;$('toast').className=`toast${error?' error':''}`;$('toast').hidden=false;state.toastTimer=setTimeout(()=>$('toast').hidden=true,error?10000:4500);}
async function action(id,fn){if(state.busy.has(id))return;state.busy.add(id);updateControls();try{await fn();}catch(e){toast(e.message,true);}finally{state.busy.delete(id);updateControls();}}
function showView(view){state.view=view==='ea'?'ea':'ai';document.querySelectorAll('.workspace').forEach(el=>el.classList.toggle('active',el.id===`view-${state.view}`));document.querySelectorAll('.nav').forEach(el=>{const on=el.dataset.view===state.view;el.classList.toggle('active',on);el.setAttribute('aria-current',on?'page':'false');});$('page-title').textContent=state.view==='ai'?'AI交易':'EA工作室';$('workspace-note').textContent=state.view==='ai'?'顺序分析与执行':'MT5 原生执行与 AI 管理';history.replaceState(null,'',`#${state.view}`);window.scrollTo({top:0,left:0,behavior:'auto'});requestAnimationFrame(drawCandles);}
