async function bootstrap(){if(state.bootstrapping)return;state.bootstrapping=true;try{const b=await api('/api/bootstrap',undefined,'GET');state.token=b.token;state.configs=b.configs||[];state.schemas=b.schemas||{};renderTabs();selectCategory(state.category);setOnline(true);await poll();}catch(e){setOnline(false,e.message);}finally{state.bootstrapping=false;}}
async function reloadConfigs(selected){const b=await api('/api/bootstrap',undefined,'GET');state.token=b.token;state.configs=b.configs||[];state.schemas=b.schemas||{};renderTabs();state.profile=state.configs.find(p=>p.category===state.category&&String(p.id)===String(selected))||active(state.category)||null;renderProfiles();renderEditor();state.eaSettingsKey=null;renderEASettings();}
async function poll(){if(state.polling)return;state.polling=true;try{
  const paths=['/api/status','/api/pipeline','/api/background','/api/ea/workspace','/api/configs'];const results=await Promise.allSettled(paths.map(path=>api(path,undefined,'GET')));
  if(results[4].status==='fulfilled')state.configs=results[4].value;
  if(results[0].status==='fulfilled'){state.status=results[0].value;setOnline(true);renderStatus();$('last-update').textContent=`同步 ${new Date().toLocaleTimeString('zh-CN',{hour12:false})}`;}else setOnline(false,results[0].reason.message);
  if(results[1].status==='fulfilled'){state.pipeline=results[1].value;renderPipeline();}else $('pipeline-status').textContent=`流程不可用：${results[1].reason.message}`;
  if(results[2].status==='fulfilled'){state.background=results[2].value;renderBackground();}else $('background').innerHTML=empty(`背景不可用：${results[2].reason.message}`);
  if(results[3].status==='fulfilled'){state.ea=results[3].value;renderEA();await syncEAActivity();}else {$('ea-bridge').textContent=`工作室不可用：${results[3].reason.message}`;$('ea-activity-state').textContent='活动状态暂不可用';}
  updateControls();
}finally{state.polling=false;}}
