function renderMarket(){const m=state.status?.market||{},frames=m.frames||{},keys=Object.keys(frames);if(!keys.includes(state.frame))state.frame=keys.includes(active('strategy')?.data.timeframe)?active('strategy').data.timeframe:keys[0]||null;const html=keys.map(k=>`<option value="${esc(k)}"${k===state.frame?' selected':''}>${esc(k)}</option>`).join('')||'<option value="">等待行情</option>';if($('chart-frame').innerHTML!==html)$('chart-frame').innerHTML=html;$('market-title').textContent=`${m.symbol||'行情'} · ${state.frame||'—'}`;$('market-time').textContent=date(m.captured_at);requestAnimationFrame(drawCandles);}
function drawCandles(){if(state.view!=='ai')return;const canvas=$('market-chart'),rect=canvas.getBoundingClientRect();if(rect.width<1)return;const bars=list(state.status?.market?.frames?.[state.frame]).filter(b=>['open','high','low','close','time'].every(k=>Number.isFinite(Number(b[k])))).slice(-90);$('chart-empty').hidden=bars.length>0;const scale=window.devicePixelRatio||1;canvas.width=rect.width*scale;canvas.height=rect.height*scale;const ctx=canvas.getContext('2d');ctx.scale(scale,scale);if(!bars.length)return;const w=rect.width,h=rect.height,right=66,top=13,bottom=26;let lo=Math.min(...bars.map(b=>b.low)),hi=Math.max(...bars.map(b=>b.high)),pad=(hi-lo)*.08||1;lo-=pad;hi+=pad;const y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom),step=(w-right)/bars.length;ctx.font='10px Consolas';ctx.fillStyle='#96a49a';ctx.strokeStyle='#27382e';for(let i=0;i<=4;i++){const p=hi-(hi-lo)*i/4;ctx.beginPath();ctx.moveTo(0,y(p));ctx.lineTo(w-right,y(p));ctx.stroke();ctx.fillText(num(p),w-right+8,y(p)+3);}bars.forEach((b,i)=>{const x=(i+.5)*step;ctx.strokeStyle=ctx.fillStyle=b.close>=b.open?'#55b69a':'#d87569';ctx.beginPath();ctx.moveTo(x,y(b.high));ctx.lineTo(x,y(b.low));ctx.stroke();ctx.fillRect(x-step*.28,Math.min(y(b.open),y(b.close)),Math.max(1,step*.56),Math.max(1,Math.abs(y(b.open)-y(b.close))));});ctx.fillStyle='#96a49a';for(let i=0;i<3;i++){const index=Math.round((bars.length-1)*i/2);const label=new Date(bars[index].time*1000).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});ctx.fillText(label,Math.min(index*step,w-right-50),h-5);}}
