function renderEASettings(){const config=active('ea'),data=state.ea?.settings||config?.data;if(!data){$('ea-strategy-fields').innerHTML=empty('EA 配置未加载');return;}const key=JSON.stringify(data);if(key===state.eaSettingsKey||state.eaDirty)return;state.eaSettingsKey=key;state.eaEditData=structuredClone(data);$('ea-ai-profile').innerHTML=providerOptions(data.ai_profile||'active');$('ea-thinking').innerHTML='<option value="true">开启</option><option value="false">关闭</option>';$('ea-thinking').value=String(data.thinking===true);const strategy=data.strategy||{},schema=resolve(schemaFor('ea').properties?.strategy,'ea');$('ea-strategy-fields').innerHTML=Object.entries(strategy).filter(([k])=>['symbol','bollinger_period','bollinger_deviation','trend_adx','range_bias','stop_atr','reward_risk','trailing_start_r','trailing_atr','breakeven_r'].includes(k)).map(([k,v])=>`<label class="${typeof v==='object'?'wide':''}">${esc(labels[k]||k)}${inputHTML(`ea-s-${k}`,k,v,schema.properties?.[k],`data-ea-strategy="${esc(k)}"`,'ea')}</label>`).join('')+`<label class="wide">自动复盘间隔 / 分钟${inputHTML('ea-review-interval','review_interval_minutes',data.review_interval_minutes,schemaFor('ea').properties?.review_interval_minutes,'','ea')}</label>`+['review_on_protection_exit','execution_magic','entry_lease_seconds','ai_controls_entries','decision_ttl_minutes','require_calendar'].filter(k=>Object.hasOwn(data,k)||Object.hasOwn(schemaFor('ea').properties||{},k)).map(k=>`<div class="wide">${fieldControl(`ea-native-${k}`,k,data[k]??schemaFor('ea').properties?.[k]?.default,schemaFor('ea').properties?.[k],`data-ea-setting="${esc(k)}"`,'ea')}</div>`).join('');}
async function saveEA(){const profile=active('ea');if(!profile)throw new Error('EA 方案未加载');const data=structuredClone(state.eaEditData||profile.data);data.ai_profile=$('ea-ai-profile').value;data.thinking=$('ea-thinking').value==='true';$('ea-strategy-fields').querySelectorAll('[data-ea-strategy]').forEach(el=>{data.strategy[el.dataset.eaStrategy]=readInput(el);});$('ea-strategy-fields').querySelectorAll('[data-ea-setting]').forEach(el=>{data[el.dataset.eaSetting]=readInput(el);});if($('ea-review-interval').value!=='')data.review_interval_minutes=Number($('ea-review-interval').value);const saved=await api(`/api/configs/ea/${encodeURIComponent(profile.id)}`,{name:profile.name,data,expected_version:profile.version},'PUT');await api(`/api/configs/ea/${encodeURIComponent(saved.id||profile.id)}/activate`,{});state.eaDirty=false;await reloadConfigs();await poll();toast('EA 配置已保存并启用');}
async function loadConversation(id){const requested=String(id);state.conversation=requested;renderConversations();state.conversationVersion=list(state.ea?.conversations).find(c=>String(c.id)===requested)?.updated_at;let c;try{c=await api(`/api/ea/conversations/${encodeURIComponent(requested)}`,undefined,'GET');}catch(e){if(state.conversation===requested)state.conversationVersion=null;throw e;}if(state.conversation!==requested)return;$('conversation-title').textContent=c.title||'EA 策略助手';const key=JSON.stringify(c.messages);if(key!==state.transcriptKey){state.transcriptKey=key;$('chat-transcript').innerHTML=list(c.messages).length?c.messages.map(m=>`<article class="message ${m.role==='user'?'user':'assistant'}"><div class="message-header"><strong>${m.role==='user'?'你':'EA 助手'}</strong><span>${date(m.created_at)}</span></div><div class="message-content${m.role==='assistant'?' markdown':''}">${m.role==='assistant'?safeMarkdown(m.content):esc(m.content)}</div>${list(m.tools).length?`<div class="detail-block"><h3>工具记录 · ${m.tools.length}</h3>${toolTrace(m.tools)}</div>`:''}</article>`).join(''):empty('输入问题，开始当前对话');$('chat-transcript').scrollTop=$('chat-transcript').scrollHeight;}}
async function createConversation(){const c=await api('/api/ea/conversations',{});state.transcriptKey=null;state.conversation=String(c.id);await poll();await loadConversation(c.id);$('chat-message').focus();return c;}
async function submitJob(path,body,kind){const job=await api(path,body);if(!job?.id)throw new Error('后端未返回任务编号');const conversation=job.conversation_id||(kind==='对话'?state.conversation:kind==='后台复盘'?reviewConversationID():null);state.jobs.set(String(job.id),{id:String(job.id),kind,conversation,explicit:true});state.activityJob={...job,kind:job.kind||kind};$('ea-job-status').textContent=`${kind} · ${stateNames[job.status]||job.status||'已提交'}`;$('ea-job-status').classList.add('job-running');renderEAActivity();updateControls();await pollJobs();}
async function pollJobs(){for(const [id,meta]of state.jobs){if(meta.polling)continue;meta.polling=true;try{
  const received=await api(`/api/ea/jobs/${encodeURIComponent(id)}`,undefined,'GET');
  const resultError=aiResultFailed(received.result?.status)||received.status==='unavailable',job={...received,kind:received.kind||meta.kind,...(resultError?{status:'error',error:received.error||received.result?.error||received.result?.content||'AI 未完成评估'}:{} )};
  state.activityJob=job;meta.conversation=job.conversation_id||meta.conversation||(meta.kind==='后台复盘'?reviewConversationID():null);
  $('ea-job-status').textContent=`${jobKind(job.kind)} · ${stateNames[job.status]||job.status}`;
  const last=list(job.events).at(-1);renderPreservingDetails('ea-active-tools',last?.state==='tool_running'?`<p class="job-running">正在调用 ${esc(last.name)}</p>`:'');renderEAActivity();
  if(['completed','done','error','failed','cancelled','interrupted'].includes(job.status)){
    state.jobs.delete(id);$('ea-job-status').classList.remove('job-running');
    if(job.error&&meta.explicit)toast(text(job.error),true);
    await poll();
    if(meta.conversation&&String(meta.conversation)===state.conversation)await loadConversation(meta.conversation);
    if(job.result&&meta.explicit&&meta.kind==='策略回测'&&job.status!=='error')showDetail(meta.kind,objectSummary(job.result)+raw('任务结果',job.result));
  }
}catch(e){$('ea-job-status').textContent=`任务状态暂不可用：${e.message}`;$('ea-activity-state').textContent=`活动状态暂不可用：${e.message}`;}finally{meta.polling=false;}}updateControls();}
function schemaFor(category){return state.schemas[category]||{};}
function resolve(prop={},category=state.category){if(prop.$ref){const k=prop.$ref.split('/').at(-1);return schemaFor(category).$defs?.[k]||prop;}if(prop.anyOf){const real=prop.anyOf.find(p=>p.type!=='null')||{};return {...resolve(real,category),nullable:prop.anyOf.some(p=>p.type==='null')};}return prop;}
function inputHTML(id,key,value,original={},extra='',category=state.category){const prop=resolve(original,category),type=prop.type||(Array.isArray(value)?'array':value===null?'string':typeof value);const choices=prop.enum;
  if(key==='ai_profile')return `<select id="${esc(id)}" data-type="string" ${extra}>${providerOptions(value)}</select>`;
  if((key==='thinking'&&prop.nullable)||key==='thinking'&&value===null)return `<select id="${esc(id)}" data-type="nullable-bool" ${extra}><option value="inherit"${value==null?' selected':''}>继承 AI 方案</option><option value="true"${value===true?' selected':''}>开启</option><option value="false"${value===false?' selected':''}>关闭</option></select>`;
  if(choices)return `<select id="${esc(id)}" data-type="${type}" ${extra}>${prop.nullable?`<option value="__null"${value==null?' selected':''}>继承 / 未指定</option>`:''}${choices.map(v=>`<option value="${esc(v)}"${v===value?' selected':''}>${esc(({shadow:'影子模拟',demo:'MT5 模拟盘',ai:'AI交易',ea:'EA工作室',model_max:'使用模型支持的最大输出',fixed:'固定单次输出上限',provider_default:'由服务端决定单次输出'})[v]||v)}</option>`).join('')}</select>`;
  if(type==='boolean')return `<label class="check" for="${esc(id)}"><input id="${esc(id)}" data-type="boolean" type="checkbox" ${value?'checked':''} ${extra}>${esc(fieldLabel(key,prop,category))}</label>`;
  if(['array','object'].includes(type))return `<textarea id="${esc(id)}" data-type="json" class="code-input" rows="3" spellcheck="false" ${extra}>${esc(JSON.stringify(value??(type==='array'?[]:{}),null,2))}</textarea>`;
  if(type==='number'||type==='integer')return `<input id="${esc(id)}" data-type="${prop.nullable?'nullable-number':'number'}" type="number" step="${type==='integer'?'1':'any'}" value="${esc(value??'')}" ${prop.minimum!==undefined?`min="${esc(prop.minimum)}"`:''} ${prop.maximum!==undefined?`max="${esc(prop.maximum)}"`:''} ${extra}>`;
  return category==='prompts'&&extra.includes('data-key')?`<textarea id="${esc(id)}" data-type="string" rows="5" ${extra}>${esc(value??'')}</textarea>`:`<input id="${esc(id)}" data-type="${prop.nullable?'nullable-string':'string'}" value="${esc(value??'')}" autocomplete="off" ${extra}>`;
}
function readInput(el){const t=el.dataset.type;if(el.value==='__null')return null;if(t==='boolean')return el.checked;if(t==='nullable-bool')return el.value==='inherit'?null:el.value==='true';if(t==='json')return JSON.parse(el.value);if(t==='number'||t==='nullable-number'){if(el.value===''&&t==='nullable-number')return null;if(el.value==='')throw new Error('数值字段不能为空');const n=Number(el.value);if(!Number.isFinite(n))throw new Error('请输入有效数字');return n;}if(t==='nullable-string'&&el.value==='')return null;return el.value;}
function renderTabs(){$('config-tabs').innerHTML=Object.keys(categories).filter(c=>state.schemas[c]||state.configs.some(p=>p.category===c)).map(c=>`<button class="tab${c===state.category?' active':''}" data-category="${esc(c)}">${esc(categories[c])}</button>`).join('');}
function selectCategory(category){state.category=category;state.profile=active(category)||state.configs.find(p=>p.category===category)||null;renderTabs();renderProfiles();renderEditor();$('history').innerHTML=empty('点击版本历史查看保存记录');}
function renderProfiles(){const profiles=state.configs.filter(p=>p.category===state.category);$('profile-select').innerHTML=profiles.map(p=>`<option value="${esc(p.id)}"${p.id===state.profile?.id?' selected':''}>${esc(p.name)}${p.active?' · 激活':''}</option>`).join('')+(state.profile?'':'<option value="" selected>新建方案</option>');}
function renderEditor(data=state.profile?.data){data=data||active(state.category)?.data||{};state.editData=structuredClone(data);$('profile-name').value=state.profile?.name||'';$('profile-meta').textContent=state.profile?`版本 ${state.profile.version} · ${state.profile.active?'已激活':'未激活'} · ${date(state.profile.updated_at)}`:'新建方案';$('config-note').textContent=notes[state.category]||'修改保存为新版本，激活后生效。';$('test-ai').hidden=state.category!=='ai';$('advanced-enabled').checked=false;$('advanced-json').value=JSON.stringify(data,null,2);const properties=schemaFor(state.category).properties||{};const keys=[...new Set([...Object.keys(data),...Object.keys(properties)])];$('config-fields').innerHTML=keys.map((key,index)=>{const value=Object.hasOwn(data,key)?data[key]:properties[key]?.default,prop=resolve(properties[key]),type=prop.type||(Array.isArray(value)?'array':typeof value);if(key==='nodes'&&Array.isArray(value))return `<div class="field wide"><div class="section-head"><h3>节点与依赖</h3><button type="button" class="text-button" id="add-node">＋ 添加节点</button></div><div id="node-editors">${nodeEditors(value)}</div></div>`;if(key==='strategy'&&state.category==='ea')return `<div class="field wide"><h3>M1 策略</h3><div class="form-grid">${Object.entries(value||{}).map(([k,v])=>`<div class="field ${typeof v==='object'?'wide':''}">${fieldControl(`ea-config-${k}`,k,v,prop.properties?.[k],`data-nested="strategy" data-subkey="${esc(k)}"`)}</div>`).join('')}</div></div>`;return `<div class="field ${['array','object'].includes(type)||state.category==='prompts'?'wide':''}">${fieldControl(`field-${index}`,key,value,properties[key],`data-key="${esc(key)}"`)}${key==='key_env'?'<small>仅填写环境变量名称</small>':''}</div>`;}).join('');updateControls();}
function nodeEditors(nodes){const promptKeys=schemaFor('logic').$defs?.AgentNode?.properties?.prompt_key?.enum||Object.keys(active('prompts')?.data||{}).filter(k=>k!=='ea_manager');return nodes.map((node,i)=>`<section class="node-editor" data-node-index="${i}"><div class="section-head"><h3>${esc(node.id)}</h3><button type="button" class="text-button" data-remove-node="${i}">删除</button></div><div class="node-form"><label>节点 ID<input data-node-key="id" data-type="string" value="${esc(node.id)}" pattern="[a-z][a-z0-9_-]{0,30}"></label><label>提示词<select data-node-key="prompt_key" data-type="string">${[...new Set([...promptKeys,node.prompt_key])].map(k=>`<option value="${esc(k)}"${node.prompt_key===k?' selected':''}>${esc(labels[k]||k)}</option>`).join('')}</select></label><label>AI 方案<select data-node-key="ai_profile" data-type="string">${providerOptions(node.ai_profile)}</select></label><label>思考<select data-node-key="thinking" data-type="nullable-bool"><option value="inherit"${node.thinking==null?' selected':''}>继承</option><option value="true"${node.thinking===true?' selected':''}>开启</option><option value="false"${node.thinking===false?' selected':''}>关闭</option></select></label><label class="check"><input type="checkbox" data-node-key="tools_enabled" data-type="boolean"${node.tools_enabled!==false?' checked':''}>工具调用</label><div class="wide"><label>依赖节点</label><div class="dependency-options">${nodes.filter((_,j)=>j!==i).map(dep=>`<label class="check"><input type="checkbox" data-dependency="${esc(dep.id)}"${list(node.depends_on).includes(dep.id)?' checked':''}>${esc(dep.id)}</label>`).join('')||'<span class="muted">无前置节点</span>'}</div></div></div></section>`).join('');}
function readForm(){if($('advanced-enabled').checked){const data=JSON.parse($('advanced-json').value);if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('配置 JSON 必须是对象');return data;}const data=structuredClone(state.editData);$('config-fields').querySelectorAll('[data-key]').forEach(el=>data[el.dataset.key]=readInput(el));$('config-fields').querySelectorAll('[data-nested]').forEach(el=>{data[el.dataset.nested]??={};data[el.dataset.nested][el.dataset.subkey]=readInput(el);});if($('node-editors'))data.nodes=[...$('node-editors').querySelectorAll('[data-node-index]')].map(section=>{const original=structuredClone(state.editData.nodes[Number(section.dataset.nodeIndex)]||{});section.querySelectorAll('[data-node-key]').forEach(el=>original[el.dataset.nodeKey]=readInput(el));original.depends_on=[...section.querySelectorAll('[data-dependency]:checked')].map(el=>el.dataset.dependency);return original;});return data;}
async function saveProfile(){const name=$('profile-name').value.trim();if(!name)throw new Error('请填写方案名称');const id=state.profile?.id||`profile-${crypto.randomUUID().slice(0,12)}`;const saved=await api(`/api/configs/${encodeURIComponent(state.category)}/${encodeURIComponent(id)}`,{name,data:readForm(),expected_version:state.profile?.version||0},'PUT');await reloadConfigs(saved.id||id);toast('已保存新版本');}
async function loadHistory(){const h=await api(`/api/configs/${encodeURIComponent(state.category)}/${encodeURIComponent(state.profile.id)}/history`,undefined,'GET');const rows=Array.isArray(h)?h:h.versions||[];$('history').innerHTML=rows.length?rows.map(v=>`<div class="history-entry">版本 ${esc(v.version)} · ${esc(v.name||state.profile.name)}<small>${date(v.updated_at??v.created_at)}</small>${v.data?raw('版本内容',v.data):''}</div>`).join(''):empty('暂无版本历史');}
function openSettings(category){if(category)selectCategory(category);$('settings-dialog').showModal();}
function showDetail(title,html){$('detail-title').textContent=title;$('detail-body').innerHTML=html;if(!$('detail-dialog').open)$('detail-dialog').showModal();}
const metricLabels={return_pct:'收益 %',total_return_pct:'收益 %',net_profit:'净损益',total_pnl:'净损益',max_drawdown_pct:'收盘权益回撤 %',win_rate:'胜率 %',profit_factor:'利润因子',trades:'交易数',trade_count:'交易数',signals:'信号数',min_lot_skips:'最小手数跳过',ending_equity:'期末权益',final_equity:'期末权益',expectancy:'单笔期望'};
function backtestSummary(result){const metrics=result.metrics||result;const gate=typeof result.approved==='boolean'?`<p class="risk-note">${result.approved?'达到后端验证门槛':'未达到验证门槛'}${list(result.reasons).length?` · ${esc(result.reasons.join('；'))}`:''}</p>`:'';if(result.training&&result.validation&&result.stress){const patch=Object.entries(result.patch||{}).map(([k,v])=>`${labels[k]||k} ${v}`).join(' · ');return gate+`<p class="muted">${patch?'候选回测 · '+esc(patch):'当前预设回测'}</p>`+table(['区段','收益 %','回撤 %','笔数'],[['校准',result.training],['验证',result.validation],['双倍成本',result.stress],['基线验证',result.baseline]].filter(([,m])=>m).map(([name,m])=>[esc(name),num(m.return_pct),num(m.max_drawdown_pct),num(m.trades,0)]));}return gate+`<div class="backtest-metrics">${Object.entries(metrics).filter(([k,v])=>typeof v==='number'&&metricLabels[k]).map(([k,v])=>`<div>${esc(metricLabels[k])}<b>${num(v,['trades','trade_count','signals','min_lot_skips'].includes(k)?0:2)}</b></div>`).join('')}</div>`;}
function renderBacktest(result){if(!result){$('backtest-summary').innerHTML=empty('尚无回测记录');return;}$('backtest-summary').innerHTML=backtestSummary(result)+(result.assumptions?`<p class="muted">${esc(text(result.assumptions))}</p>`:'');$('backtest-trades').innerHTML=list(result.trades).length?table(['开仓','平仓','方向','入场','离场','损益'],result.trades.map(t=>[esc(date(t.entry_time??t.time)),esc(date(t.exit_time)),esc(t.side??t.action),num(t.entry??t.entry_price),num(t.exit??t.exit_price),num(t.pnl??t.profit)])):empty('回测无成交');}
async function loadJournal(){const paths=['/api/cycles?limit=30','/api/audit?limit=50','/api/backtest'];const results=await Promise.allSettled(paths.map(path=>api(path,undefined,'GET')));results.forEach((r,i)=>{if(r.status==='rejected'){[$('cycles'),$('audit'),$('backtest-summary')][i].innerHTML=empty(r.reason.message);return;}if(i===0){state.cycles=Array.isArray(r.value)?r.value:r.value.cycles||[];$('cycles').innerHTML=state.cycles.length?state.cycles.map(c=>`<button class="record" data-cycle="${esc(c.id)}">${esc(c.signal?.action||c.status)} · ${esc(c.signal?.reason||'周期记录')}<small>${date(c.created_at)} · ${num(c.latency_ms,0)} ms</small></button>`).join(''):empty('尚无周期');}else if(i===1){const rows=Array.isArray(r.value)?r.value:r.value.events||[];$('audit').innerHTML=rows.length?rows.map(e=>`<article class="audit-event"><small>${date(e.created_at??e.time)}</small><p>${esc(e.action??e.event??e.kind)}</p><div class="muted">${esc(text(e.summary??e.message??e.detail??e.data??''))}</div></article>`).join(''):empty('暂无审计');}else renderBacktest(r.value);});}
