function safeURL(value){try{const u=new URL(String(value));return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}}
function link(value,label){const url=safeURL(value);return url?`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label||value)} ↗</a>`:esc(label||value);}
function linkedText(value){const input=String(value??'');const matcher=/https?:\/\/[^\s<>"']+/g;let html='',last=0;for(const hit of input.matchAll(matcher)){html+=esc(input.slice(last,hit.index))+link(hit[0]);last=hit.index+hit[0].length;}return html+esc(input.slice(last));}
const indicatorLabels={time:'收盘 K 线时间',close:'收盘价',atr:'ATR',atr_percent:'ATR / 价格 %',atr_baseline:'ATR 基线',volatility_ratio:'波动倍率',rsi:'RSI',adx:'ADX',di_plus:'+DI',di_minus:'−DI',macd:'MACD 线',macd_signal:'MACD 信号线',macd_histogram:'MACD 柱',bb_middle:'布林中轨',bb_lower:'布林下轨',bb_upper:'布林上轨',bb_width_percent:'布林宽度 %',bb_percent_b:'布林位置 %B',return_1_pct:'单根变化 %',relative_tick_volume:'相对 Tick 量'};
function indicatorLabel(key){return indicatorLabels[key]||(key.startsWith('ema_')?`EMA ${key.slice(4)}`:key);}
function indicatorValue(key,value,packet){if(value==null)return '未预热 / 缺失';if(key==='time')return date(value);if(typeof value!=='number')return text(value);const price=key==='close'||key.startsWith('ema_')||['atr','atr_baseline','bb_middle','bb_upper','bb_lower'].includes(key);const precision=price?Math.min(5,Math.max(0,Number(packet.contract?.digits)||2)):['rsi','adx','di_plus','di_minus'].includes(key)?2:3;return num(value,precision);}
function frameIndicators(tf,frame,packet,all=false){const indicators=frame.indicators||{},keyOrder=['close','ema_20','ema_50','ema_200','rsi','atr','adx','macd_histogram','bb_lower','bb_upper'];const keys=all?Object.keys(indicators):keyOrder.filter(k=>Object.hasOwn(indicators,k));let html=kv(keys.map(k=>[indicatorLabel(k),indicatorValue(k,indicators[k],packet)]));if(!all)html+=kv([['20 根支撑',num(frame.support_20,packet.contract?.digits??2)],['20 根阻力',num(frame.resistance_20,packet.contract?.digits??2)]]);if(all){const q=frame.quality||{};html+=kv([['最近收盘',date(q.last_closed_at)],['行情年龄',q.age_seconds==null?'—':`${num(q.age_seconds,1)} 秒`],['预热',q.warmup_sufficient===true?'充分':q.warmup_sufficient===false?'不足':'未返回'],['最近 100 根缺口',q.gaps_in_last_100??'—']]);}return html;}
function packetSummary(packet){if(!packet)return empty('数据包尚未返回');const frames=packet.frames||{},selected=Object.hasOwn(frames,state.frame)?state.frame:Object.keys(frames)[0];let html=kv([['资料时间',date(packet.as_of_utc)],['点差 / 点',num(packet.spread_points,1)],['行情来源',packet.provenance?.source||'未返回']]);if(!selected)return html+empty('暂无周期指标');html+=`<div class="detail-block"><h3>${esc(selected)} · 关键收盘指标</h3>${frameIndicators(selected,frames[selected],packet)}</div>`;html+=Object.entries(frames).map(([tf,frame])=>`<details class="advanced"><summary>${esc(tf===selected?`${tf} 完整指标与质量`:`${tf} 指标与质量`)}</summary>${frameIndicators(tf,frame,packet,true)}</details>`).join('');return html;}
function backgroundRow(item,kind){const stamp=date(item.time_utc??item.published_at),source=item.source||'来源未返回';return `<article class="background-row"><span>${esc(kind)}<br>${esc(item.impact==='high'?'高影响':item.impact==='medium'?'中影响':item.impact==='low'?'低影响':'')}</span><div><strong>${item.url?link(item.url,item.title):esc(item.title)}</strong>${item.summary?`<p>${esc(item.summary)}</p>`:''}<p>${safeURL(source)?link(source):esc(source)}${item.url&&!safeURL(source)?` · ${link(item.url,'原文')}`:''}</p></div><span>${esc(stamp)}</span></article>`;}
function providerName(value){const url=safeURL(value);if(!url)return text(value);const u=new URL(url);return u.hostname.includes('federalreserve.gov')?`美联储 ${u.pathname.includes('speeches')?'讲话':'政策'}`:u.hostname;}
function renderBackground(){const b=state.background||{},now=Date.now()/1000,events=[...list(b.events)].sort((a,c)=>(a.time_utc??0)-(c.time_utc??0)),news=[...list(b.news)].sort((a,c)=>(c.time_utc??0)-(a.time_utc??0));const selectedEvents=events.filter(e=>e.impact==='high'&&Number(e.time_utc)>=now).slice(0,3),selectedNews=news.slice(0,3);const restEvents=events.filter(e=>!selectedEvents.includes(e)),restNews=news.slice(3);
  $('background-time').textContent=`资料 ${date(b.updated_at)}`;
  const calendar=b.calendar_fresh===true?`日历有效 · ${date(b.calendar_updated_at||b.updated_at)}`:'日历缺失或过期';
  const newsStatus=b.news_fresh===true?`新闻采集有效 · ${date(b.news_updated_at)}`:`新闻采集缺失或过期${b.news_updated_at?` · 上次 ${date(b.news_updated_at)}`:''}`;
  const providers=list(b.providers).map(p=>`<span class="${p.status==='ok'?'muted':'negative'}">${safeURL(p.name)?link(p.name,providerName(p.name)):esc(providerName(p.name))} ${p.status==='ok'?`${p.count??0} 条`:`不可用${p.error?` (${esc(p.error)})`:''}`}</span>`).join(' · ');
  const rows=(selectedEvents.length?selectedEvents.map(e=>backgroundRow(e,'临近事件')).join(''):empty(b.calendar_fresh?'已提供日历中没有未来高影响事件':'没有有效日历，未来事件风险待确认'))+(selectedNews.length?selectedNews.map(n=>backgroundRow(n,'最新新闻')).join(''):empty('当前没有可显示的新闻'));
  const more=(restEvents.length||restNews.length)?`<details class="advanced"><summary>其余资料 · 事件 ${restEvents.length} / 新闻 ${restNews.length}</summary>${restEvents.map(e=>backgroundRow(e,'事件')).join('')}${restNews.map(n=>backgroundRow(n,'新闻')).join('')}</details>`:'';
  renderPreservingDetails('background',`<div class="background-health"><span class="${b.calendar_fresh?'muted':'negative'}">${esc(calendar)}</span><span class="${b.news_fresh?'muted':'negative'}">${esc(newsStatus)}</span>${providers?`<div>${providers}</div>`:''}</div>${rows}${more}${b.coverage_note?`<details class="advanced"><summary>覆盖范围与数据源</summary><p class="muted">${esc(b.coverage_note)}</p>${b.providers?raw('数据源检查记录',b.providers):''}</details>`:''}`);
}
function safeMarkdown(value){
  return window.FusionMarkdown.render(value);
}

function scheduleChanges(){
  return Hours.patch(Number($('ea-session-start').value),Number($('ea-session-end').value),$('ea-session-all-day').checked,$('ea-session-weekends').checked,scheduleEditor.offset);
}
function renderEAHours(){
  const row=active('workflow'),risk=active('risk')?.data,e=state.status?.engine||{};
  if(!row||!risk)return;
  const key=`${row.id}:${row.version}`;
  if(!scheduleEditor.dirty&&!scheduleEditor.saving&&scheduleEditor.loadedKey!==key){
    const options=Array.from({length:24},(_,h)=>`<option value="${h}">${Hours.clock(h)}</option>`).join('');
    $('ea-session-start').innerHTML=$('ea-session-end').innerHTML=options;
    $('ea-session-start').value=String(Hours.mod(row.data.session_start_utc+scheduleEditor.offset));
    $('ea-session-end').value=String(Hours.mod(row.data.session_end_utc+scheduleEditor.offset));
    $('ea-session-all-day').checked=row.data.session_start_utc===row.data.session_end_utc;
    $('ea-session-weekends').checked=row.data.block_weekends;
    scheduleEditor.original=structuredClone(row);scheduleEditor.loadedKey=key;
  }
  const tz=scheduleEditor.offset===8?'北京时间':'UTC';
  $('ea-session-current').textContent=`当前：${tz} ${Hours.windowLabel(row.data,scheduleEditor.offset)} · UTC ${Hours.windowLabel(row.data,0)} · 方案 v${row.version}`;
  const gate=Hours.gate(Date.now(),row.data,list(risk.sessions));
  const localNow=new Date().toLocaleTimeString('zh-CN',{timeZone:scheduleEditor.offset===8?'Asia/Shanghai':'UTC',hour12:false});
  $('ea-session-status').textContent=`${localNow} · ${gate.weekend?'周末关闭':!gate.inWindow?'时间窗口未开放':!gate.risk?'时段风控不可确认':gate.risk.risk_scale<=0?'时段风险预算为 0':'时间条件允许'}`;
  $('ea-session-status').className=`badge${gate.allowed?' running':''}`;
  const excluded=list(risk.sessions).filter(s=>s.risk_scale===0).map(s=>`${s.name}：${Hours.windowLabel({session_start_utc:s.start_utc,session_end_utc:s.end_utc%24},scheduleEditor.offset)}`);
  $('ea-session-risk-summary').textContent=excluded.length?`其他时段限制（${tz}）：${excluded.join('；')} 风险预算为 0，仍禁止入场。可在“时段风控设置”调整。`:'时段风险预算均大于 0；是否入场仍由 AI 许可、信号、新闻风控及市场开市共同决定。';
  try{
    const draft=scheduleChanges();
    $('ea-session-preview').textContent=`待保存：${tz} ${Hours.windowLabel(draft,scheduleEditor.offset)} → UTC ${Hours.windowLabel(draft,0)}${draft.block_weekends?'；周末关闭（北京时间周六 08:00–周一 08:00）':''}`;
  }catch(error){$('ea-session-preview').textContent=error.message;}
  $('ea-session-save').textContent=scheduleEditor.saving?'正在保存并确认…':e.running||e.armed?'暂停管理并保存时段':'保存并发布到 EA';
  $('ea-session-save').disabled=scheduleEditor.saving||!state.online||!scheduleEditor.original;
  $('ea-session-reload').disabled=scheduleEditor.saving||!state.online;
  for(const id of ['ea-session-zone','ea-session-all-day','ea-session-start','ea-session-end','ea-session-weekends'])$(id).disabled=scheduleEditor.saving||(['ea-session-start','ea-session-end'].includes(id)&&$('ea-session-all-day').checked);
}
async function saveEAHours(){
  if(scheduleEditor.saving)return;
  const changes=scheduleChanges(),original=structuredClone(scheduleEditor.original);
  let stored=false;
  scheduleEditor.saving=true;updateControls();renderEAHours();
  try{
    await Hours.save({original,changes,request:api,onStage:(stage,message)=>{
      if(stage==='saved')stored=true;
      $('ea-session-result').textContent=message;
    }});
    scheduleEditor.dirty=false;
    toast('EA 已确认新时段；请解锁并重新启动管理');
  }catch(error){$('ea-session-result').textContent=error.message;toast(error.message,true);}
  finally{
    scheduleEditor.saving=false;updateControls();
    if(stored){scheduleEditor.dirty=false;scheduleEditor.loadedKey=null;await reloadConfigs(state.profile?.id);}
    await poll();renderEAHours();
  }
}
$('ea-session-zone').addEventListener('change',()=>{
  const next=Number($('ea-session-zone').value),shift=next-scheduleEditor.offset;
  $('ea-session-start').value=String(Hours.mod(Number($('ea-session-start').value)+shift));
  $('ea-session-end').value=String(Hours.mod(Number($('ea-session-end').value)+shift));
  scheduleEditor.offset=next;renderEAHours();
});
for(const id of ['ea-session-start','ea-session-end','ea-session-all-day','ea-session-weekends'])$(id).addEventListener('change',()=>{scheduleEditor.dirty=true;$('ea-session-result').textContent='尚未保存';renderEAHours();});
$('ea-session-form').addEventListener('submit',event=>{event.preventDefault();action('ea-session-save',saveEAHours);});
$('ea-session-risk-settings').addEventListener('click',()=>openSettings('risk'));
$('ea-session-reload').addEventListener('click',()=>action('ea-session-reload',async()=>{
  await reloadConfigs(state.profile?.id);
  scheduleEditor.dirty=false;scheduleEditor.loadedKey=null;
  $('ea-session-result').textContent='已恢复当前保存的时段';renderEAHours();
}));
